# The right hand now retains the broom, and the pan is separate on the left.
# Carry and gradually yaw the broom clear of the objects, then approach the pan handle.
def yaw_down(a):
    c = np.cos(a/2)
    s = np.sin(a/2)
    return [0.5*(c-s),-0.5*(c+s),0.5*(c-s),0.5*(c+s)]
qb = yaw_down(1.57079632679)
if servo_line('right',[0.29,-0.14,1.025]+qb,0,max_steps=58,increment=0.010,q_increment=0.04,settle=4):
    if move_pose('left',[-0.18,-0.015,0.99]+qdown,1,steps=20):
        servo_line('left',[-0.18,0.005,0.933]+qdown,1,max_steps=18,increment=0.006,settle=4)

